import itertools, random
import sys

def check(edges):
    n=15
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v);adj[v].add(u)
    # degree >=5
    if any(len(adj[i])<5 for i in range(n)):
        return False
    # max clique size <=4
    # brute force up to 5
    for k in range(5, n+1):
        for combo in itertools.combinations(range(n), k):
            if all((j in adj[i]) for i,j in itertools.combinations(combo,2)):
                return False
    # chromatic number <=4 using simple backtrack
    colors=[-1]*n
    order=sorted(range(n), key=lambda x: -len(adj[x]))
    def dfs(idx):
        if idx==n:
            return True
        v=order[idx]
        for c in range(4):
            if all(colors[nb]!=c for nb in adj[v]):
                colors[v]=c
                if dfs(idx+1):
                    return True
                colors[v]=-1
        return False
    return dfs(0)

